 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    boxes = []
    box_colors = set()
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 4:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r0,c) for c in range(c0,c1+1)} | {(r1,c) for c in range(c0,c1+1)} | {(r,c0) for r in range(r0,r1+1)} | {(r,c1) for r in range(r0,r1+1)}
        if all(grid[r][c] == color for r,c in perimeter):
            boxes.append((color,r0,r1,c0,c1))
            box_colors.add(color)

    # Count the isolated speckles of each non-frame color; each frame is filled
    # with the color whose speckle count most closely matches its checkerboard.
    speckles = Counter(v for row in grid for v in row if v != 0 and v not in box_colors)
    available = set(speckles)
    assignments = {}
    for color, r0, r1, c0, c1 in sorted(boxes, key=lambda b: (b[2]-b[1]-1)*(b[4]-b[3]-1)):
        ih, iw = r1-r0-1, c1-c0-1
        target = (ih*iw+1)//2
        if available:
            chosen = min(available, key=lambda x: (abs(speckles[x]-target), x))
            assignments[color] = chosen
            available.remove(chosen)
    out = [[0 for _ in range(w)] for _ in range(h)]
    for color, r0, r1, c0, c1 in boxes:
        for c in range(c0,c1+1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0,r1+1):
            out[r][c0] = color
            out[r][c1] = color
        fill = assignments.get(color)
        if fill is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r-r0-1 + c-c0-1) % 2 == 0:
                        out[r][c] = fill
    return out
